import {characteristicTitle} from './preflight.js?v=2.5.12';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function readinessBanner(report,{screen=null,error=null,running=false}={}){
 const problems=(screen?.issues.length||0)+(screen?.failures.length||0),blocked=report.errors.length||problems||error;
 const title=report.errors.length?report.errors.length+' input '+(report.errors.length===1?'needs':'items need')+' attention':problems?problems+' characteristic '+(problems===1?'issue needs':'issues need')+' review':error?'Characteristic screening could not finish':screen?'Input and interpolation checks passed':running?'Checking interpolated characteristics…':'Interpolation checks pending';
 const detail=report.errors.length?'Fix setup inputs before interpolation screening':problems?'Review negative projections and failed model queries before analysis':error?'Retry screening before analysis':screen?(report.warnings.length?report.warnings.length+' reference / data notes to review':'Ready for analysis'):'Static input checks passed · open Check inputs to screen actual waveform queries';
 return `<section class="readiness ${blocked?'needs-input':screen?'ready':'pending'}" aria-label="Analysis input checks"><div><strong>${esc(title)}</strong><span>${esc(detail)}</span></div><a href="#checks" class="ghost small">${blocked?'Review & fix inputs':'View input checks'}</a></section>`;
}
export function readinessList(report){const groups=new Map();for(const issue of report.issues){const key=[issue.device,issue.part,issue.category].filter(Boolean).join(' · ');let group=groups.get(key);if(!group){group=[];groups.set(key,group);}group.push(issue);}return `<p>Fix invalid or duplicated characteristic points before analysis. When setup checks pass, the Check Inputs page screens the exact interpolated waveform queries, including negative extrapolated physical magnitudes, before the full analysis. Thermal convergence is also evaluated during this screening.</p><div class="check-counts"><strong>${report.errors.length} inputs to fix</strong><span>${report.warnings.length} notes to review</span></div>${groups.size?[...groups].map(([name,issues])=>`<section class="panel input-check-group"><h2>${esc(name)}</h2>${issues.map(issue=>`<div class="input-check ${issue.severity}"><div><span class="check-kind">${issue.severity==='error'?'Fix before analysis':'Review'}</span><p>${esc(issue.message)}</p>${issue.details?`<details><summary>More detail</summary><p class="caption">${esc(issue.details)}</p></details>`:''}</div><button class="ghost small" data-fix-issue="${esc(issue.id)}">Open & fix<span class="sr-only">: ${esc(issue.message)}</span></button><button type="button" class="ghost small" data-issue-help="${esc(issue.id)}">Help with this issue ?</button></div>`).join('')}</section>`).join(''):'<div class="notice">Static setup checks passed. Review interpolation and physical-value screening below before analysis.</div>'}`;}
export function curveIssueHTML(issues){if(!issues.length)return '<p class="caption curve-valid">Curve points pass the data checks.</p>';return `<div class="curve-data-issues" role="status">${issues.map(issue=>`<div class="notice ${issue.severity==='error'?'error':'warn'}"><strong>${Number.isInteger(issue.iteration)?'Iteration '+(issue.iteration+1)+': ':''}</strong>${esc(issue.message)}</div>`).join('')}</div>`;}
